bool isStaticValue(mlir::Value value) {
    return ir::ConstantFolder::FoldIntValue(value).has_value();
}

std::optional<int64_t> getStaticValue(mlir::Value value) {
    return ir::ConstantFolder::FoldIntValue(value);
